import{_ as a,H as t,f as _,i as l}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"Q76 | 安全：商用大模型如何防泄？","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q76｜安全：商用大模型如何防泄？.md","filePath":"致程序员：AI百问百答/Q76｜安全：商用大模型如何防泄？.md","lastUpdated":1795559851000}'),r={name:"致程序员：AI百问百答/Q76｜安全：商用大模型如何防泄？.md"};function o(p,e,i,s,n,d){return t(),_("div",null,[...e[0]||(e[0]=[l('<h1 id="q76-安全-商用大模型如何防泄" tabindex="-1">Q76 | 安全：商用大模型如何防泄？ <a class="header-anchor" href="#q76-安全-商用大模型如何防泄" aria-label="Permalink to &quot;Q76 | 安全：商用大模型如何防泄？&quot;">​</a></h1><ul><li>作者介绍：彭靖田，Google Developers Expert</li></ul><p>Q：在工作中用大模型怎么保证公司业务、代码、数据的安全？</p><p>彭靖田：如果你是在国内做 To C 类的业务，这个天然就有各种各样的法律法规方面的要求，首先你得满足监管部门的要求，另外如果你面向国内的用户，那么肯定也不允许你去直接使用海外的模型服务，肯定是要做本地化的部署。国外的话，比如欧盟的 GDPR 等相关地域的法律法规也都要去遵守。</p><p>概括而言，一般要注意以下几个方面：</p><ol><li><p>数据隔离和本地部署：为了避免数据泄露，敏感数据尽量在本地部署的模型上进行推理，如通过 Hugging Face Transformers 等工具。</p></li><li><p>隐私数据加密：对传入和传出的数据加密，确保敏感信息不会通过 API 或日志泄露。可以使用隐私增强技术（如差分隐私）。</p></li><li><p>模型访问控制：设置访问权限，限制谁可以调用大模型，并在企业内部引入监控系统，以避免不安全的访问或不合理的调用行为。</p></li><li><p>模型推理日志记录与审查：启用详细的日志记录，并定期审查模型的推理行为，确保大模型未产生任何潜在风险。</p></li></ol>',6)])])}const m=a(r,[["render",o]]);export{f as __pageData,m as default};
